sp_widget.client_script:
function($scope) {

    var c = this;


    // =====================================================
    // PAGE NAVIGATION
    // =====================================================

    c.openPage = function(pageId) {

        if (!pageId) {
            return;
        }

        window.location.href =
            "student?id=" + pageId;

    };


    // =====================================================
    // OPEN CASE
    // =====================================================

    c.openCase = function(sysId) {

        if (!sysId) {
            return;
        }

        window.location.href =
            "student?id=case_details&sys_id=" +
            sysId;

    };


    // =====================================================
    // INITIAL DATA
    // =====================================================

    if (!c.data) {
        c.data = {};
    }

    if (!c.data.components) {
        c.data.components = [];
    }

    if (!c.data.alerts) {
        c.data.alerts = [];
    }

    if (!c.data.healthTrend) {
        c.data.healthTrend = [];
    }

    if (!c.data.recommendation) {

        c.data.recommendation = {
            title: '',
            description: '',
            page: ''
        };

    }


    // =====================================================
    // REFRESH
    // =====================================================

    c.refresh = function() {

        c.server.get({
            action: 'refresh'
        }).then(function(response) {

            if (response &&
                response.data) {

                angular.extend(
                    c.data,
                    response.data
                );

            }

        });

    };

}

sp_widget.css:
.vg-summary-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 14px;
    width: 100%;
    box-sizing: border-box;
}

.vg-summary-card {
    min-width: 0;
    min-height: 205px;
    background: #ffffff;
    border: 1px solid #d9e4ee;
    border-radius: 10px;
    padding: 18px;
    box-sizing: border-box;
    box-shadow: 0 2px 8px rgba(27,58,91,.06);
    cursor: pointer;
    transition: .15s ease;
}

.vg-summary-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 18px rgba(27,58,91,.12);
}

.vg-card-title {
    color: #506b87;
    font-size: 13px;
    font-weight: 600;
}

.vg-score-area {
    display: flex;
    align-items: center;
    gap: 18px;
    margin-top: 18px;
}

.vg-score-circle {
    --score: 0;
    width: 82px;
    height: 82px;
    min-width: 82px;
    border-radius: 50%;
    background:
        conic-gradient(
            #35ae70 calc(var(--score) * 1%),
            #e8eef4 0
        );
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
}

.vg-score-circle::after {
    content: "";
    position: absolute;
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #fff;
}

.vg-score-circle span {
    position: relative;
    z-index: 2;
    color: #173b61;
    font-size: 15px;
    font-weight: 700;
}

.vg-document-area {
    display: flex;
    align-items: center;
    gap: 18px;
    margin-top: 17px;
}

.vg-document-circle {
    width: 82px;
    height: 82px;
    min-width: 82px;
    border-radius: 50%;
    border: 5px solid #4c82da;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #244f87;
    font-size: 16px;
    font-weight: 700;
}

.vg-risk-circle {
    width: 82px;
    height: 82px;
    margin-top: 17px;
    border-radius: 50%;
    border: 5px solid #dcae47;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #3d4d60;
    font-size: 14px;
    font-weight: 700;
}

.vg-risk-circle.risk-low {
    border-color: #39aa6c;
    color: #29945c;
}

.vg-risk-circle.risk-medium {
    border-color: #e2b54f;
    color: #a87916;
}

.vg-risk-circle.risk-high {
    border-color: #d85757;
    color: #c23e3e;
}

.vg-calendar-icon {
    margin-top: 14px;
    font-size: 28px;
}

.vg-days {
    display: flex;
    align-items: baseline;
    gap: 6px;
}

.vg-days strong {
    color: #173b61;
    font-size: 28px;
}

.vg-days span {
    color: #d75252;
    font-size: 12px;
    font-weight: 600;
}

.vg-summary-card h3 {
    margin: 6px 0 4px;
    color: #173b61;
    font-size: 15px;
}

.vg-summary-card p {
    color: #73879a;
    font-size: 11px;
    line-height: 1.5;
}

.vg-summary-card a {
    color: #2878c8;
    font-size: 11px;
    text-decoration: none;
}

.vg-summary-card a:hover {
    text-decoration: underline;
}


/* Service Portal width fix */

.vg-compliance-page {
    width: 100%;
    min-height: 100vh;
    background: #f5f8fc;
    color: #173b61;
    font-family: "Segoe UI", Arial, sans-serif;
    overflow-x: hidden;
}

.vg-compliance-header {
    width: 100%;
    min-height: 68px;
    background: #071f3d;
    color: white;
    display: flex;
    align-items: center;
    padding: 0 24px;
    box-sizing: border-box;
}

.vg-compliance-body {
    width: 100%;
    padding: 18px 22px 30px;
    box-sizing: border-box;
}

.row {
    margin-left: 0 !important;
    margin-right: 0 !important;
}

.container-fluid {
    width: 100% !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
}

sp_widget.script:
(function() {

    data.complianceScore = 0;

    data.complianceMessage =
        'No compliance case found.';

    data.documentsCompleted = 0;
    data.documentsTotal = 0;
    data.documentsPending = 0;
    data.documentsStatus = 'Pending';

    data.riskLevel = 'Unknown';
    data.riskScore = 0;

    data.riskMessage =
        'Risk assessment unavailable.';

    data.deadlineDays = null;
    data.deadlineTitle = '';
    data.deadlineDate = '';

    data.components = [];
    data.alerts = [];
    data.healthTrend = [];

    data.scoreImprovement = 0;

    data.student = {

        program: '',
        university: '',
        programStartDate: '',
        expectedGraduation: '',
        currentTerm: '',
        daysInProgram: ''

    };

    data.recommendation = {

        title: '',
        description: '',
        page: ''

    };


    // =====================================================
    // CURRENT USER
    // =====================================================

    var currentUserId =
        gs.getUserID();


    if (!currentUserId) {
        return;
    }


    // =====================================================
    // FIND USER'S VISA CASE
    // =====================================================

    /*
     * Your Visa Cases table is the custom VisaGuardian
     * table shown in your screenshots.
     *
     * Replace ONLY this table name if your exact
     * technical table name is different.
     */

    var caseGR =
        new GlideRecord('x_snc_visaguardian_ai_visa_cases');


    if (!caseGR.isValid()) {

        gs.error(
            'VisaGuardian: Visa Cases table is invalid.'
        );

        return;

    }


    /*
     * Find the student's case.
     *
     * We first try common user-reference fields.
     */

    var foundCase = false;


    if (caseGR.isValidField('student')) {

        caseGR.addQuery(
            'student',
            currentUserId
        );

    } else if (caseGR.isValidField('opened_by')) {

        caseGR.addQuery(
            'opened_by',
            currentUserId
        );

    } else if (caseGR.isValidField('caller_id')) {

        caseGR.addQuery(
            'caller_id',
            currentUserId
        );

    } else {

        /*
         * Last option: assigned user.
         */

        if (caseGR.isValidField('assigned_to')) {

            caseGR.addQuery(
                'assigned_to',
                currentUserId
            );

        }

    }


    caseGR.orderByDesc('sys_created_on');

    caseGR.setLimit(1);

    caseGR.query();


    if (caseGR.next()) {

        foundCase = true;

    }


    // =====================================================
    // NO CASE
    // =====================================================

    if (!foundCase) {

        data.complianceMessage =
            'No active compliance case found.';

        data.components = [];

        data.alerts = [];

        return;

    }


    // =====================================================
    // COMPLIANCE SCORE
    // =====================================================

    if (caseGR.isValidField('compliance_score')) {

        var score =
            parseInt(
                caseGR.getValue(
                    'compliance_score'
                ),
                10
            );


        if (!isNaN(score)) {

            data.complianceScore =
                Math.max(
                    0,
                    Math.min(
                        100,
                        score
                    )
                );

        }

    }


    if (data.complianceScore >= 80) {

        data.complianceMessage =
            'You are maintaining good compliance. Keep going!';

    } else if (data.complianceScore >= 60) {

        data.complianceMessage =
            'Some compliance items need your attention.';

    } else {

        data.complianceMessage =
            'Several compliance requirements need attention.';

    }


    // =====================================================
    // DOCUMENT INFORMATION
    // =====================================================

    data.documentsTotal = 9;

    data.documentsCompleted = 0;


    /*
     * Documents submitted/uploaded.
     */

    if (caseGR.isValidField('documents_submitted')) {

        if (
            caseGR.getValue(
                'documents_submitted'
            ) == 'true'
        ) {

            data.documentsCompleted++;

        }

    }


    if (caseGR.isValidField('documents_uploaded')) {

        if (
            caseGR.getValue(
                'documents_uploaded'
            ) == 'true'
        ) {

            data.documentsCompleted++;

        }

    }


    /*
     * Keep the value within 0-9.
     */

    if (data.documentsCompleted > 9) {

        data.documentsCompleted = 9;

    }


    data.documentsPending =
        data.documentsTotal -
        data.documentsCompleted;


    if (
        data.documentsCompleted ==
        data.documentsTotal
    ) {

        data.documentsStatus =
            'Complete';

    } else {

        data.documentsStatus =
            'Pending';

    }


    // =====================================================
    // RISK
    // =====================================================

    if (caseGR.isValidField('compliance_score')) {

        var riskScore =
            100 -
            data.complianceScore;


        data.riskScore =
            Math.max(
                0,
                Math.min(
                    100,
                    riskScore
                )
            );


        if (data.riskScore <= 25) {

            data.riskLevel =
                'Low';

            data.riskMessage =
                'Your current compliance risk is low.';

        } else if (data.riskScore <= 60) {

            data.riskLevel =
                'Medium';

            data.riskMessage =
                'Review suggested for financial and compliance documents.';

        } else {

            data.riskLevel =
                'High';

            data.riskMessage =
                'Immediate attention is recommended.';

        }

    }


    // =====================================================
    // DEADLINE
    // =====================================================

    if (
        caseGR.isValidField('due_date') &&
        !gs.nil(
            caseGR.getValue(
                'due_date'
            )
        )
    ) {

        var dueDate =
            new GlideDateTime(
                caseGR.getValue(
                    'due_date'
                )
            );


        var now =
            new GlideDateTime();


        var difference =
            GlideDateTime.subtract(
                now,
                dueDate
            );


        var seconds =
            parseInt(
                difference.getNumericValue(),
                10
            ) / 1000;


        var days =
            Math.ceil(
                seconds / 86400
            );


        if (days >= 0) {

            data.deadlineDays =
                days;

            data.deadlineTitle =
                'Visa Case Deadline';

            data.deadlineDate =
                dueDate.getLocalDate();

        }

    }


    // =====================================================
    // COMPLIANCE COMPONENTS
    // =====================================================

    addComponent(
        'Identity Verification',
        'Passport and identity documents',
        'Verified',
        '✓',
        ''
    );


    addComponent(
        'Admission Verification',
        'Admission letter and I-20',
        'Verified',
        '✓',
        ''
    );


    addComponent(
        'Passport Verification',
        'Passport validity and details',
        'Verified',
        '✓',
        ''
    );


    /*
     * Financial documents.
     */

    var financialStatus =
        'Verified';


    if (
        caseGR.isValidField('decision') &&
        caseGR.getValue('decision') ==
        'Additional Documents Required'
    ) {

        financialStatus =
            'Review';

    }


    addComponent(
        'Financial Documents',
        'Financial proof and statements',
        financialStatus,
        '!',
        ''
    );


    addComponent(
        'Academic Verification',
        'Transcripts and academic records',
        'Verified',
        '🎓',
        ''
    );


    addComponent(
        'SEVIS Registration',
        'SEVIS fee and registration',
        'Verified',
        '🌐',
        ''
    );


    addComponent(
        'Health Insurance',
        'Health insurance coverage',
        'Verified',
        '♡',
        ''
    );


    /*
     * Travel signature.
     */

    var travelStatus =
        'Pending';


    if (
        caseGR.isValidField('dso_decision')
    ) {

        var dsoDecision =
            caseGR.getValue(
                'dso_decision'
            );


        if (
            dsoDecision ==
            'Approved'
        ) {

            travelStatus =
                'Verified';

        }

    }


    addComponent(
        'Travel Signature',
        'I-20 travel signature',
        travelStatus,
        '✈',
        ''
    );


    /*
     * Visa application.
     */

    var visaStatus =
        'Pending';


    if (
        caseGR.isValidField('decision')
    ) {

        var decision =
            caseGR.getValue(
                'decision'
            );


        if (
            decision ==
            'Approved'
        ) {

            visaStatus =
                'Verified';

        }

    }


    addComponent(
        'Visa Application',
        'Visa application and interview',
        visaStatus,
        '✓',
        ''
    );



    // =====================================================
    // HEALTH TREND
    // =====================================================

    data.healthTrend = [

        {
            month: 'Mar',
            value: data.complianceScore,
            left: 5
        },

        {
            month: 'Apr',
            value: data.complianceScore,
            left: 25
        },

        {
            month: 'May',
            value: data.complianceScore,
            left: 45
        },

        {
            month: 'Jun',
            value: data.complianceScore,
            left: 65
        },

        {
            month: 'Jul',
            value: data.complianceScore,
            left: 82
        },

        {
            month: 'Aug',
            value: data.complianceScore,
            left: 96
        }

    ];


    data.scoreImprovement = 0;


    // =====================================================
    // KEY INFORMATION
    // =====================================================

    /*
     * Read information from the current user.
     */

    var userGR =
        new GlideRecord(
            'sys_user'
        );


    if (
        userGR.get(
            currentUserId
        )
    ) {

        data.student.program =
            userGR.getDisplayValue(
                'department'
            );


        data.student.university =
            userGR.getDisplayValue(
                'company'
            );

    }


    /*
     * Current semester and student-specific
     * fields can be populated if they exist
     * directly on the Visa Case.
     */

    if (
        caseGR.isValidField(
            'current_semester'
        )
    ) {

        data.student.currentTerm =
            caseGR.getDisplayValue(
                'current_semester'
            );

    }


    if (
        caseGR.isValidField(
            'expected_graduation'
        )
    ) {

        data.student.expectedGraduation =
            caseGR.getDisplayValue(
                'expected_graduation'
            );

    }


    if (
        caseGR.isValidField(
            'program_start_date'
        )
    ) {

        data.student.programStartDate =
            caseGR.getDisplayValue(
                'program_start_date'
            );

    }


    // =====================================================
    // RECOMMENDATION
    // =====================================================

    if (
        data.documentsPending > 0
    ) {

        data.recommendation = {

            title:
                'Complete financial document review',

            description:
                'Your compliance records require verification. Please review and upload any missing documents.',

            page:
                'vg_doc_upload'

        };

    } else if (
        data.deadlineDays !== null &&
        data.deadlineDays <= 14
    ) {

        data.recommendation = {

            title:
                'Upcoming compliance deadline',

            description:
                'Your next immigration-related deadline is approaching. Review the deadline details and required action.',

            page:
                'vg_deadlines'

        };

    } else {

        data.recommendation = {

            title:
                'Keep your compliance up to date',

            description:
                'Continue monitoring your documents, deadlines, and visa requirements.',

            page:
                'vg_deadlines'

        };

    }


    // =====================================================
    // ALERTS
    // =====================================================

    if (
        data.documentsPending > 0
    ) {

        data.alerts.push({

            type:
                'warning',

            icon:
                '⚠',

            title:
                'Financial document review required',

            description:
                'Please review your pending compliance documents.',

            time:
                'Current'

        });

    }


    if (
        data.deadlineDays !== null &&
        data.deadlineDays <= 14
    ) {

        data.alerts.push({

            type:
                'info',

            icon:
                'i',

            title:
                'Visa deadline approaching',

            description:
                data.deadlineTitle +
                ' is due in ' +
                data.deadlineDays +
                ' days.',

            time:
                'Upcoming'

        });

    }


    if (
        data.complianceScore >= 80
    ) {

        data.alerts.push({

            type:
                'success',

            icon:
                '✓',

            title:
                'Compliance status healthy',

            description:
                'Your current compliance score is ' +
                data.complianceScore +
                '%.',

            time:
                'Current'

        });

    }


    // =====================================================
    // HELPER
    // =====================================================

    function addComponent(
        name,
        description,
        status,
        icon,
        date
    ) {

        data.components.push({

            name:
                name,

            description:
                description,

            status:
                status,

            icon:
                icon,

            date:
                date

        });

    }


})();
